<script setup lang="ts">
import {onMounted} from 'vue';
import {t,formatDate} from '@kuaixie/i18n';
import {useCouplerSettings,type CouplerField,type CouplerProvider,type CouplerMode} from '@kuaixie/ui/useCouplerSettings';
import {createAdminApi} from '../api/client';
const p=useCouplerSettings(createAdminApi(),async(title,body)=>window.confirm(title+'\n'+body));
const categoryKeys:Record<string,string>=Object.fromEntries(['AI','MINIAPP','RTC','SUBSCRIBE','FACE','SMS','PRIVACY_NUMBER','WXPAY','TRANSLATE','OSS','FEATURES','ALIPAY','EMAIL','OAUTH','KYC','MAP','SEARCH','BANK_CARD','LOGISTICS','AIRLINE','RAIL'].map(code=>[code,'coupler.category.'+code]));
function categoryLabel(code:string,name:string){return categoryKeys[code]?t(categoryKeys[code]):name}
function modeLabel(mode:CouplerMode){return t(mode==='LIVE'?'coupler.live':'coupler.sandbox')}
function fieldStatus(key:string){if(p.configuration.value.unreadableFields.includes(key))return t('coupler.fieldUnreadable');return t(p.configuration.value.configuredFields.includes(key)?'coupler.fieldSaved':'coupler.fieldMissing')}
function saved(provider:CouplerProvider){return provider.configurationByMode[p.mode.value]}
function label(key:string){return p.provider.value?.fields.find(field=>field.key===key)?.label||key}
function canActivate(){return p.modeSupported.value&&['implemented','native','bridge','sdk_client','protocol_client','business_protocol','local_policy'].includes(p.provider.value?.capability||'')}
function multiline(field:CouplerField){return field.inputType==='textarea'||/(pem|private[_-]?key|certificate|template[_-]?json|config[_-]?json)/i.test(field.key)}
function docsAllowed(value:string){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}
function capability(value:string){return t(({implemented:'coupler.capabilityNative',native:'coupler.capabilityNative',bridge:'coupler.capabilityBridge',reference_only:'coupler.capabilityReference',sdk_client:'coupler.capabilitySdk',protocol_client:'coupler.capabilityProtocol',business_protocol:'coupler.capabilityBusiness',local_policy:'coupler.capabilityPolicy'} as Record<string,string>)[value]||'coupler.capabilityUnknown')}
onMounted(()=>{void p.load()});
</script>
<template><section class="coupler-settings surface"><header><h2>{{t('coupler.title')}}</h2><p>{{t('coupler.help')}}</p><p class="scope-note">{{t('coupler.scopeNotice')}}</p></header><p v-if="p.error.value" role="alert">{{p.error.value}}</p><p v-if="p.notice.value" role="status">{{p.notice.value}}</p><button type="button" :disabled="p.busy.value" @click="p.load()">{{t('coupler.refresh')}}</button><template v-if="p.settings.value"><section class="runtime" :class="{live:p.settings.value.runtime.mode==='LIVE'}"><div><strong>{{t('coupler.activeMode')}} · {{modeLabel(p.settings.value.runtime.mode)}}</strong><small>{{t('coupler.revision')}} {{p.settings.value.runtime.revision}}</small></div><label>{{t('coupler.runtimeTarget')}}<select v-model="p.runtimeTarget.value" :disabled="p.busy.value"><option value="SANDBOX">{{modeLabel('SANDBOX')}}</option><option value="LIVE">{{modeLabel('LIVE')}}</option></select></label><button type="button" :disabled="p.busy.value||p.dirty.value||p.runtimeTarget.value===p.settings.value.runtime.mode" @click="p.changeRuntime()">{{t('coupler.applyRuntime')}}</button></section><p v-if="p.settings.value.encryptionReady===false" role="alert">{{t('coupler.keyUnavailable')}}</p><div class="coupler-grid"><nav class="categories" :aria-label="t('coupler.categories')"><h3>{{t('coupler.categories')}} · {{p.settings.value.categories.length}}</h3><button v-for="category in p.settings.value.categories" :key="category.code" type="button" :disabled="p.busy.value" :class="{selected:category.code===p.categoryCode.value}" @click="p.chooseCategory(category.code)">{{categoryLabel(category.code,category.name)}}<small>{{category.providers.length}} {{t('coupler.providerCount')}}</small></button></nav><main><template v-if="p.category.value"><h3>{{categoryLabel(p.category.value.code,p.category.value.name)}}</h3><p>{{p.category.value.description}}</p><div class="mode-tabs" role="group" :aria-label="t('coupler.editingMode')"><button v-for="mode in (['SANDBOX','LIVE'] as const)" :key="mode" type="button" :class="{selected:p.mode.value===mode,live:mode==='LIVE'}" :disabled="p.busy.value" @click="p.chooseMode(mode)">{{modeLabel(mode)}}</button></div><p>{{t('coupler.editingMode')}}: <strong>{{modeLabel(p.mode.value)}}</strong> · {{t('coupler.activeMode')}}: {{modeLabel(p.settings.value.runtime.mode)}}</p><p>{{t('coupler.modeIsolation')}}</p><div class="providers"><button v-for="provider in p.category.value.providers" :key="provider.code" type="button" :disabled="p.busy.value" :class="{selected:provider.code===p.providerCode.value}" @click="p.chooseProvider(provider.code)"><strong>{{provider.name}}</strong><small>{{saved(provider)?.selected?t('coupler.currentSelection'):t('coupler.notSelected')}} · {{saved(provider)?.enabled?t('coupler.enabled'):t('coupler.disabled')}}</small></button></div><form v-if="p.provider.value" @submit.prevent="p.save()" autocomplete="off"><header><h4>{{p.provider.value.name}} · {{modeLabel(p.mode.value)}}</h4><small>{{t('coupler.revision')}} {{p.configuration.value.revision}}<span v-if="p.configuration.value.updatedAt"> · {{formatDate(p.configuration.value.updatedAt)}}</span></small></header><div class="capabilities"><p>{{t('coupler.protocol')}}: {{capability(p.provider.value.capability)}}</p><p>{{t('coupler.sdkStatus')}}: <strong>{{t(p.provider.value.sdkAvailable?'coupler.sdkAvailable':'coupler.sdkUnavailable')}}</strong></p><p>{{t('coupler.consumerStatus')}}: <strong>{{t(p.provider.value.consumerWired?'coupler.consumerWired':'coupler.consumerPending')}}</strong></p><p>{{t('coupler.businessStatus')}}: <strong>{{t(p.provider.value.businessVerified?'coupler.businessVerified':'coupler.businessPending')}}</strong></p><p>{{t('coupler.supportedModes')}}: {{p.provider.value.supportedModes.map(modeLabel).join(' / ')||t('coupler.noSupportedModes')}}</p><a v-if="docsAllowed(p.provider.value.docs)" :href="p.provider.value.docs" target="_blank" rel="noopener noreferrer">{{t('coupler.docs')}}</a><details v-if="p.provider.value.implementedOperations.length"><summary>{{t('coupler.implementedOperations')}}</summary><ul><li v-for="operation in p.provider.value.implementedOperations" :key="operation">{{operation}}</li></ul></details></div><p>{{t('coupler.secretHelp')}}</p><p v-if="!p.modeSupported.value" class="scope-note">{{t('coupler.modeUnsupported')}}</p><p v-if="p.needsRefresh.value" role="alert">{{t('coupler.refreshRequired')}}</p><fieldset :disabled="p.busy.value||p.needsRefresh.value"><div class="fields"><label v-for="field in p.provider.value.fields" :key="field.key" :class="{missing:p.draftMissing.value.includes(field.key)}"><span>{{field.label}} <b v-if="field.required">*</b> <code>{{field.key}}</code></span><small>{{fieldStatus(field.key)}} · {{t(field.required?'coupler.required':'coupler.optional')}}</small><select v-if="field.options?.length" v-model="p.draft.values[field.key]" :disabled="p.draft.clearFields[field.key]"><option value="">{{t('coupler.preserveOrUnset')}}</option><option v-for="option in field.options" :key="option.value" :value="option.value">{{option.label}}</option></select><select v-else-if="field.inputType==='boolean'" v-model="p.draft.values[field.key]" :disabled="p.draft.clearFields[field.key]"><option value="">{{t('coupler.preserveOrUnset')}}</option><option value="true">{{t('coupler.flagOn')}}</option><option value="false">{{t('coupler.flagOff')}}</option></select><textarea v-else-if="multiline(field)" v-model="p.draft.values[field.key]" :disabled="p.draft.clearFields[field.key]" :placeholder="field.secret?t('coupler.secretPlaceholder'):field.placeholder||''" :class="{masked:field.secret}" maxlength="16000" spellcheck="false" autocomplete="off"/><input v-else v-model="p.draft.values[field.key]" :type="field.secret?'password':'text'" :disabled="p.draft.clearFields[field.key]" :placeholder="field.secret?t('coupler.secretPlaceholder'):field.placeholder||''" maxlength="16000" autocomplete="off" spellcheck="false"/><span v-if="p.configuration.value.configuredFields.includes(field.key)||p.configuration.value.unreadableFields.includes(field.key)" class="clear-field"><input v-model="p.draft.clearFields[field.key]" type="checkbox"/>{{t('coupler.clearField')}}</span></label></div><div class="switches"><label><input v-model="p.draft.enabled" type="checkbox" :disabled="!p.draft.enabled&&(!canActivate())"/>{{t('coupler.enableProvider')}}</label><label><input v-model="p.draft.selected" type="checkbox" :disabled="!p.draft.selected&&(!canActivate()||!p.provider.value.consumerWired)"/>{{t('coupler.selectProvider')}}</label></div><p>{{t('coupler.selectionHelp')}}</p><p v-if="!p.provider.value.consumerWired">{{t('coupler.consumerPending')}}</p><p v-if="p.dirty.value" role="status">{{t('coupler.unsaved')}}</p><p v-if="p.draftMissing.value.length">{{t('coupler.draftMissing')}}: {{p.draftMissing.value.map(label).join(', ')}}</p><button :disabled="p.settings.value.encryptionReady===false">{{t('coupler.saveMode',{mode:modeLabel(p.mode.value)})}}</button></fieldset></form><section v-if="p.provider.value" class="local-validation"><h4>{{t('coupler.localCheck')}}</h4><p>{{t('coupler.localCheckHelp')}}</p><button type="button" :disabled="p.busy.value||p.dirty.value||p.needsRefresh.value" @click="p.validate()">{{t('coupler.checkSaved')}}</button><template v-if="p.validation.value"><p>{{modeLabel(p.validation.value.mode)}} · {{t('coupler.revision')}} {{p.validation.value.revision}}</p><p><strong>{{t(p.validation.value.ready?'coupler.localReady':'coupler.localNotReady')}}</strong></p><p>{{t('coupler.sdkStatus')}}: {{t(p.validation.value.sdkAvailable?'coupler.sdkAvailable':'coupler.sdkUnavailable')}}</p><p>{{t('coupler.businessStatus')}}: {{t(p.validation.value.businessVerified?'coupler.businessVerified':'coupler.businessPending')}}</p><p v-if="p.validation.value.missingFields.length">{{t('coupler.missingFields')}}: {{p.validation.value.missingFields.map(label).join(', ')}}</p><p v-if="p.validation.value.invalidFields.length">{{t('coupler.invalidFields')}}: {{p.validation.value.invalidFields.map(label).join(', ')}}</p><p v-if="p.validation.value.unreadableFields.length">{{t('coupler.unreadableFields')}}: {{p.validation.value.unreadableFields.map(label).join(', ')}}</p><ul v-if="p.validation.value.checks?.length"><li v-for="check in p.validation.value.checks" :key="check.code">{{check.code}} · {{check.status}} · {{check.message}}</li></ul></template></section></template></main></div></template></section></template>
<style scoped>.coupler-settings{padding:24px;border:1px solid #cbd5e1;border-radius:18px;margin:20px 0;background:var(--kx-surface,#fff)}.coupler-settings h2,.coupler-settings h3,.coupler-settings h4{margin:0 0 12px}.coupler-settings p{line-height:1.7;font-size:13px}.coupler-settings small{display:block;line-height:1.7;font-size:12px}.coupler-settings button{padding:10px 14px;border:1px solid #cbd5e1;border-radius:8px;background:var(--kx-surface,#fff);color:inherit;cursor:pointer}.coupler-settings button:disabled{opacity:.5;cursor:default}.coupler-settings button.selected{background:#0e7490;border-color:#0e7490;color:#fff}.scope-note{padding:12px;background:#fff7e5;color:#704300;border-radius:9px}.runtime{display:flex;gap:16px;align-items:center;flex-wrap:wrap;padding:16px;margin:16px 0;background:#eaf5ff;border-radius:10px}.runtime.live{background:#fff1f0;border:1px solid #b42318}.runtime label{display:grid;gap:6px}.coupler-grid{display:grid;grid-template-columns:minmax(160px,220px) minmax(0,1fr);gap:20px;margin-top:20px}.categories{display:grid;align-content:start;gap:7px;max-height:1100px;overflow:auto}.categories button{text-align:left}.mode-tabs,.providers,.switches{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.providers button{text-align:left;flex:1 1 190px}.mode-tabs button.live:not(.selected){border-color:#b42318;color:#b42318}.coupler-settings form,.local-validation{border:1px solid #cbd5e1;padding:18px;border-radius:10px;margin-top:18px}.capabilities{background:var(--kx-background,#f8fafc);padding:12px;border-radius:8px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.fields label{display:grid;gap:6px;align-content:start}.fields code{font-size:11px;opacity:.7;overflow-wrap:anywhere}.fields label.missing{border-left:3px solid #b54708;padding-left:9px}.coupler-settings input:not([type=checkbox]),.coupler-settings select,.coupler-settings textarea{padding:10px;border:1px solid #cbd5e1;border-radius:7px;max-width:100%;box-sizing:border-box}.coupler-settings textarea{min-height:110px}.masked{-webkit-text-security:disc}.switches label,.clear-field{display:flex;gap:7px;align-items:center;font-size:13px}.coupler-settings [role=alert]{color:#b42318}.coupler-settings fieldset{border:0;padding:0;margin:0}@media(max-width:850px){.coupler-grid{grid-template-columns:1fr}.categories{display:flex;overflow-x:auto;max-height:none}.categories h3{display:none}.categories button{flex:0 0 155px}.fields{grid-template-columns:1fr}}</style>
